/bin/zsh -lc "python3 - <<'PY'
import os, stat, subprocess
from pathlib import Path
from collections import Counter
src = Path.cwd() / 'input words.txt'
out = Path.cwd() / 'verified words.txt'
created = False
try:
    if not src.is_file() or not os.access(src, os.R_OK):
        raise ValueError('Source is not a readable regular file')
    if not out.parent.is_dir():
        raise ValueError('Output parent directory does not exist')
    if os.path.lexists(out):
        raise ValueError('Output collision: an entry already occupies the requested output path')
    original = src.read_bytes()
    words = original.split(b'\\n')
    if words and words[-1] == b'':
        words.pop()
    try:
        decoded = [w.decode('utf-8') for w in words]
    except UnicodeDecodeError:
        raise ValueError('Source is unsuitable: not UTF-8 plain text')
    if any(not w or any(c.isspace() or not c.isprintable() for c in w) for w in decoded):
        raise ValueError('Source is unsuitable: expected one nonempty word per line without whitespace or control characters')
    with out.open('xb') as saved:
        created = True
        result = subprocess.run(['sort', str(src)], stdout=saved, stderr=subprocess.PIPE, env={**os.environ, 'LC_ALL': 'C'})
    if result.returncode:
        raise ValueError('sort failed: ' + result.stderr.decode(errors='replace'))
    saved_bytes = out.read_bytes()
    saved_words = saved_bytes.split(b'\\n')
    if saved_words and saved_words[-1] == b'':
        saved_words.pop()
    if any(a > b for a, b in zip(saved_words, saved_words[1:])):
        raise ValueError('Saved output failed C-locale byte-order verification')
    if Counter(saved_words) "'!= Counter(words):
        raise ValueError('"'Saved output failed word multiset verification')
    if src.read_bytes() "'!= original:
        raise ValueError('"'Source bytes changed')
    print(f'Verified: {out}\\nC-locale byte order and all {len(words)} words including duplicates verified; source bytes unchanged.')
except Exception as e:
    print(f'STOP: {e}')
    if created:
        print(f'Unverified output may remain at: {out}')
    raise SystemExit(1)
PY"
